insert into public.recipes (slug,name,image,time_mins,kcal,servings,description,steps,source) values ('caesar-salad','Caesar Salad','https://images.unsplash.com/photo-1550304943-4f24f54ddde9?w=600&q=80',10,350,2,'A classic: crisp romaine, parmesan, croutons and a creamy dressing.',$steps$[{"section":"Make the Dressing","duration":180,"instructions":[{"text":"In a bowl, add ","highlight":"2 tbsp mayonnaise","after":", 1 tsp Dijon mustard and 1 tsp Worcestershire."},{"text":"Grate ","highlight":"1 clove garlic","after":" straight in, then squeeze in the juice of half a lemon."},{"text":"Whisk hard for ~30 seconds until it turns pale and creamy, then stir in half the grated parmesan (about 20g)."}],"tip":"Whisk vigorously to emulsify — if it looks watery, add a little more mayo and keep whisking.","youtubeQuery":"caesar salad dressing from scratch"},{"section":"Prep the Romaine","duration":240,"instructions":[{"text":"Cut the base off ","highlight":"1 head romaine","after":" and separate the leaves."},{"text":"Stack a few leaves, then chop across into 2-inch (bite-size) ribbons."},{"text":"Rinse under cold water and spin or pat completely dry — wet leaves won’t hold dressing."}],"tip":"Dry the leaves twice. Any water left on them dilutes the dressing and it slides off.","youtubeQuery":"how to cut romaine for caesar salad"},{"section":"Toss & Finish","duration":120,"instructions":[{"text":"Put the romaine in a large bowl. Pour over about two-thirds of the dressing."},{"text":"Toss with tongs for 20–30 seconds until every leaf is lightly, evenly coated — add more dressing only if dry."},{"text":"Scatter over ","highlight":"1 cup croutons","after":", the remaining parmesan, and a heavy crack of black pepper. Serve immediately."}],"tip":"Add croutons at the very end so they stay crunchy, not soggy.","youtubeQuery":"how to toss caesar salad"}]$steps$::jsonb,'recipe-dataset') on conflict (slug) do update set name=excluded.name,image=excluded.image,time_mins=excluded.time_mins,kcal=excluded.kcal,servings=excluded.servings,description=excluded.description,steps=excluded.steps,source=excluded.source;
