insert into public.recipes (slug,name,image,time_mins,kcal,servings,description,steps,source) values ('aglio-olio-spaghetti','Aglio e Olio Spaghetti','https://images.unsplash.com/photo-1621996346565-e3dbc646d9a9?w=600&q=80',12,550,2,'Garlic, olive oil, chili and pasta. Five ingredients, big flavor.',$steps$[{"section":"Boil the Pasta","duration":480,"instructions":[{"text":"Bring a large pot of water to a rolling boil and salt it well (it should taste like the sea)."},{"text":"Add ","highlight":"200g spaghetti","after":" and cook 1 minute short of the packet time, so it stays al dente."},{"text":"Before draining, scoop out and reserve ","highlight":"1 cup pasta water","after":"."}],"tip":"The starchy pasta water is what makes the sauce glossy later — don’t skip saving it.","youtubeQuery":"how to boil spaghetti al dente"},{"section":"Infuse the Oil","duration":240,"instructions":[{"text":"Thinly slice ","highlight":"4 cloves garlic","after":" and finely chop 1 chili (deseed for less heat)."},{"text":"In a cold pan add ","highlight":"3 tbsp olive oil","after":", the garlic and chili, then turn heat to medium-low."},{"text":"Cook gently 3–4 minutes, stirring, until the garlic is pale gold and fragrant — do not let it brown."}],"tip":"Start garlic in cold oil and go low — burnt garlic turns bitter in seconds.","youtubeQuery":"garlic chili oil for aglio olio"},{"section":"Toss & Serve","duration":120,"instructions":[{"text":"Add the drained spaghetti to the pan with a splash (about 1/4 cup) of the reserved pasta water."},{"text":"Toss over medium heat 1–2 minutes until the oil and water emulsify and cling to the strands."},{"text":"Off the heat, stir through ","highlight":"30g parmesan","after":" and a pinch of salt. Serve at once."}],"tip":"Keep it moving in the pan — the tossing is what turns oil + water into a silky sauce.","youtubeQuery":"aglio e olio finishing technique"}]$steps$::jsonb,'json-cookbook') on conflict (slug) do update set name=excluded.name,image=excluded.image,time_mins=excluded.time_mins,kcal=excluded.kcal,servings=excluded.servings,description=excluded.description,steps=excluded.steps,source=excluded.source;
