insert into public.recipes (slug,name,image,time_mins,kcal,servings,description,steps,source) values ('caesar-wrap','Caesar Wrap','https://images.unsplash.com/photo-1608897013039-887f21d8c804?w=600&q=80',10,380,2,'Caesar salad rolled into a soft tortilla with grilled chicken.',$steps$[{"section":"Prep the Ingredients","duration":300,"instructions":[{"text":"Wash, peel and chop as needed: ","highlight":"Tortillas, Chicken Breast, Romaine Lettuce, Parmesan","after":"."},{"text":"Measure everything out and keep it within reach before you turn on the heat."}],"tip":"Mise en place — prepping first keeps a fast recipe from getting away from you.","youtubeQuery":"Caesar Wrap prep"},{"section":"Cook","duration":420,"instructions":[{"text":"Heat a pan with a little oil over medium heat and add the aromatics (onion/garlic) first if using."},{"text":"Add the main ingredients for Caesar Wrap and cook, stirring, until done through."},{"text":"Season with salt and pepper, tasting as you go."}],"tip":"Add ingredients in order of how long they take — hardest/longest first.","youtubeQuery":"how to cook Caesar Wrap"},{"section":"Plate & Serve","duration":120,"instructions":[{"text":"Check seasoning one last time, plate up, and add any fresh garnish."},{"text":"Serve while hot."}],"tip":"A final squeeze of acid (lemon) or fresh herb lifts almost any dish.","youtubeQuery":"Caesar Wrap plating"}]$steps$::jsonb,'recipe-dataset') on conflict (slug) do update set name=excluded.name,image=excluded.image,time_mins=excluded.time_mins,kcal=excluded.kcal,servings=excluded.servings,description=excluded.description,steps=excluded.steps,source=excluded.source;
