insert into public.recipes (slug,name,image,time_mins,kcal,servings,description,steps,source) values ('guacamole','Guacamole','https://images.unsplash.com/photo-1600335895229-6e75511892c8?w=600&q=80',7,300,3,'Ripe avocado mashed with lime, onion, cilantro and chili.',$steps$[{"section":"Prep the Aromatics","duration":180,"instructions":[{"text":"Finely dice ","highlight":"half an onion","after":" and 1 chili (deseed for milder heat)."},{"text":"Chop a small handful of cilantro, stems and all."},{"text":"Roll and cut ","highlight":"1 lime","after":" in half, ready to juice."}],"tip":"Dice the onion small so no single bite is overpowering.","youtubeQuery":"how to dice onion for guacamole"},{"section":"Mash the Avocado","duration":180,"instructions":[{"text":"Halve ","highlight":"2 avocados","after":", remove the pits, and scoop the flesh into a bowl."},{"text":"Mash with a fork to your liking — leave it a little chunky for texture."},{"text":"Immediately squeeze in the juice of the lime to stop it browning."}],"tip":"Add the lime juice right after mashing — the acid keeps the guac green.","youtubeQuery":"how to mash avocado guacamole"},{"section":"Combine & Season","duration":120,"instructions":[{"text":"Fold in the onion, chili and cilantro."},{"text":"Add a good pinch of salt, then taste and adjust salt and lime."},{"text":"Serve right away, or press cling film onto the surface to hold it."}],"tip":"Season, then taste — guacamole almost always needs a bit more salt and lime than you think.","youtubeQuery":"guacamole seasoning tips"}]$steps$::jsonb,'recipe-dataset') on conflict (slug) do update set name=excluded.name,image=excluded.image,time_mins=excluded.time_mins,kcal=excluded.kcal,servings=excluded.servings,description=excluded.description,steps=excluded.steps,source=excluded.source;
