insert into public.recipes (slug,name,image,time_mins,kcal,servings,description,steps,source) values ('veggie-omelette','Veggie Omelette','https://images.unsplash.com/photo-1510693206972-df098062cb71?w=600&q=80',8,260,1,'Fluffy eggs folded over sauteed peppers, onion and cheese.',$steps$[{"section":"Prep & Beat","duration":150,"instructions":[{"text":"Finely dice ","highlight":"half a bell pepper","after":" and a quarter of an onion."},{"text":"Crack ","highlight":"3 eggs","after":" into a bowl, add a pinch of salt, and beat until fully combined."}],"tip":"Beat the eggs well — 20 seconds of whisking makes the omelette light.","youtubeQuery":"how to beat eggs for omelette"},{"section":"Soften the Veg","duration":180,"instructions":[{"text":"Melt ","highlight":"1 tbsp butter","after":" in a non-stick pan over medium heat."},{"text":"Add the pepper and onion and cook 2–3 minutes until softened, then spread evenly."}],"tip":"Cook the veg first so it’s tender — raw pepper in a 2-minute omelette stays crunchy.","youtubeQuery":"sauteing peppers and onions"},{"section":"Cook & Fold","duration":150,"instructions":[{"text":"Pour the eggs over the veg. As they set, drag the edges to the centre and tilt the pan so raw egg runs under."},{"text":"When almost set, scatter ","highlight":"30g cheese","after":" over one half."},{"text":"Fold the omelette over the cheese, cook 30 seconds more, and slide onto a plate."}],"tip":"Take it off while the top is just barely soft — it finishes cooking on the plate.","youtubeQuery":"how to fold an omelette"}]$steps$::jsonb,'tandoor') on conflict (slug) do update set name=excluded.name,image=excluded.image,time_mins=excluded.time_mins,kcal=excluded.kcal,servings=excluded.servings,description=excluded.description,steps=excluded.steps,source=excluded.source;
insert into public.recipe_ingredients (recipe_id,canonical,display,quantity,unit,optional,staple) values
