insert into public.recipes (slug,name,image,time_mins,kcal,servings,description,steps,source) values ('garlic-butter-salmon','Garlic Butter Salmon','https://images.unsplash.com/photo-1467003909585-2f8a72700288?w=600&q=80',20,410,2,'Pan-seared salmon in a lemony garlic butter.',$steps$[{"section":"Prep the Fish","duration":180,"instructions":[{"text":"Pat ","highlight":"2 salmon fillets","after":" completely dry and season both sides with salt and pepper."},{"text":"Thinly slice ","highlight":"3 cloves garlic","after":" and cut 1 lemon into wedges."}],"tip":"Drying the salmon is the secret to a crisp, golden sear.","youtubeQuery":"how to prep salmon fillet"},{"section":"Sear Skin-Side Down","duration":300,"instructions":[{"text":"Heat a pan over medium-high. Add a little oil, then lay the salmon skin-side down."},{"text":"Press gently for 10 seconds so it doesn’t curl, and sear 4–5 minutes until the skin is crisp."},{"text":"Flip and cook 2 more minutes."}],"tip":"Don’t move the fillet while it sears — let the crust form before flipping.","youtubeQuery":"how to pan sear salmon"},{"section":"Garlic Butter","duration":120,"instructions":[{"text":"Lower the heat. Add ","highlight":"2 tbsp butter","after":" and the sliced garlic to the pan."},{"text":"As the butter foams, spoon it over the salmon for 1 minute. Finish with a squeeze of lemon."}],"tip":"Basting with the foaming butter is what carries the garlic flavour into the fish.","youtubeQuery":"garlic butter basting salmon"}]$steps$::jsonb,'recipe-dataset') on conflict (slug) do update set name=excluded.name,image=excluded.image,time_mins=excluded.time_mins,kcal=excluded.kcal,servings=excluded.servings,description=excluded.description,steps=excluded.steps,source=excluded.source;
