  ((select id from public.recipes where slug = 'garlic-butter-salmon'),'black pepper','Black Pepper',1,'tsp',false,true);
insert into public.recipes (slug,name,image,time_mins,kcal,servings,description,steps,source) values ('chickpea-curry','Chickpea Curry','https://images.unsplash.com/photo-1585937421612-70a008356fbe?w=600&q=80',25,390,3,'Chickpeas simmered in a spiced tomato and onion gravy.',$steps$[{"section":"Build the Base","duration":300,"instructions":[{"text":"Finely dice ","highlight":"1 onion","after":"; grate 2 cloves garlic and 1 tbsp ginger; chop 2 tomatoes."},{"text":"Heat ","highlight":"2 tbsp oil","after":" in a pan and cook the onion 5 minutes until soft and golden."},{"text":"Stir in the garlic, ginger and ","highlight":"1 tsp cumin","after":"; cook 1 minute until fragrant."}],"tip":"Cook the onion properly golden first — it’s the flavour foundation of the curry.","youtubeQuery":"how to make curry base onion ginger garlic"},{"section":"Simmer","duration":600,"instructions":[{"text":"Add the chopped tomatoes and cook 4–5 minutes until they break down into a paste."},{"text":"Drain and add ","highlight":"2 cans chickpeas","after":" with a splash of water."},{"text":"Simmer 8–10 minutes, stirring occasionally, until thickened. Season with salt to taste."}],"tip":"Mash a few chickpeas against the pan to naturally thicken the sauce.","youtubeQuery":"chickpea curry simmer"}]$steps$::jsonb,'tandoor') on conflict (slug) do update set name=excluded.name,image=excluded.image,time_mins=excluded.time_mins,kcal=excluded.kcal,servings=excluded.servings,description=excluded.description,steps=excluded.steps,source=excluded.source;
