insert into public.recipes (slug,name,image,time_mins,kcal,servings,description,steps,source) values ('banana-pancakes','Banana Pancakes','https://images.unsplash.com/photo-1567620905732-2d1ec7ab7445?w=600&q=80',15,330,2,'Soft pancakes sweetened with ripe mashed banana.',$steps$[{"section":"Make the Batter","duration":240,"instructions":[{"text":"Mash ","highlight":"2 ripe bananas","after":" in a bowl until fairly smooth."},{"text":"Whisk in ","highlight":"2 eggs","after":" and 150ml milk."},{"text":"Fold in ","highlight":"150g flour","after":" just until combined — a few lumps are fine, don’t overmix."}],"tip":"Overmixing develops gluten and makes pancakes tough. Stop as soon as the flour disappears.","youtubeQuery":"banana pancake batter"},{"section":"Cook the Pancakes","duration":360,"instructions":[{"text":"Melt a little butter in a pan over medium-low heat."},{"text":"Pour in small rounds of batter. Cook until bubbles form on top and the edges set (~2 min)."},{"text":"Flip and cook 1–2 minutes more until golden. Repeat with the rest."}],"tip":"Flip only when bubbles pop and stay open — flipping too early tears them.","youtubeQuery":"how to flip pancakes"}]$steps$::jsonb,'json-cookbook') on conflict (slug) do update set name=excluded.name,image=excluded.image,time_mins=excluded.time_mins,kcal=excluded.kcal,servings=excluded.servings,description=excluded.description,steps=excluded.steps,source=excluded.source;
