insert into public.recipes (slug,name,image,time_mins,kcal,servings,description,steps,source) values ('shrimp-fried-rice','Shrimp Fried Rice','https://images.unsplash.com/photo-1603133872878-684f208fb84b?w=600&q=80',18,520,2,'Wok-tossed rice with shrimp, egg and vegetables.',$steps$[{"section":"Prep Everything","duration":240,"instructions":[{"text":"Dice ","highlight":"1 carrot","after":" and half an onion small. Beat 2 eggs."},{"text":"Pat ","highlight":"200g shrimp","after":" dry. Have 300g cooked, cold rice ready (day-old is best)."}],"tip":"Cold, day-old rice fries up separate and non-mushy. Fresh hot rice turns to clumps.","youtubeQuery":"fried rice mise en place"},{"section":"Cook Shrimp & Egg","duration":240,"instructions":[{"text":"Heat ","highlight":"2 tbsp oil","after":" in a wok on high. Sear the shrimp ~1 min per side until pink, then remove."},{"text":"Pour the beaten eggs into the wok, scramble quickly, and push to the side."}],"tip":"High heat and a hot wok — fried rice is fast; have everything within reach.","youtubeQuery":"wok fried rice technique"},{"section":"Fry & Combine","duration":240,"instructions":[{"text":"Add the onion and carrot, stir-fry 2 minutes."},{"text":"Add the rice, breaking up clumps, and toss 2–3 minutes."},{"text":"Return the shrimp and egg, add ","highlight":"2 tbsp soy sauce","after":", and toss to combine. Serve hot."}],"tip":"Spread the rice against the hot wok and let it sit a few seconds between tosses for a light char.","youtubeQuery":"shrimp fried rice finish"}]$steps$::jsonb,'recipe-dataset') on conflict (slug) do update set name=excluded.name,image=excluded.image,time_mins=excluded.time_mins,kcal=excluded.kcal,servings=excluded.servings,description=excluded.description,steps=excluded.steps,source=excluded.source;
