insert into public.recipes (slug,name,image,time_mins,kcal,servings,description,steps,source) values ('greek-yogurt-berry-bowl','Greek Yogurt Berry Bowl','https://images.unsplash.com/photo-1488477181946-6428a0291777?w=600&q=80',5,220,1,'Creamy yogurt topped with berries and a drizzle of honey.',$steps$[{"section":"Assemble","duration":120,"instructions":[{"text":"Spoon ","highlight":"200g Greek yogurt","after":" into a bowl and smooth the top."},{"text":"Scatter over ","highlight":"100g berries","after":" (halve any large strawberries)."},{"text":"Drizzle with ","highlight":"1 tbsp honey","after":" and serve."}],"tip":"Add the honey just before eating so it sits on top instead of sinking in.","youtubeQuery":"greek yogurt breakfast bowl"}]$steps$::jsonb,'json-cookbook') on conflict (slug) do update set name=excluded.name,image=excluded.image,time_mins=excluded.time_mins,kcal=excluded.kcal,servings=excluded.servings,description=excluded.description,steps=excluded.steps,source=excluded.source;
